import os
import json
from typing import Any, Dict, List, Optional

from openai import OpenAI

client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))


def extract_invoice_fields(invoice_text: str) -> Dict[str, Any]:
    """
    Extract vendor, date, total, and line-item fields from invoice text using OpenAI's hosted API.
    Returns a normalized dictionary.
    """
    schema = {
        "name": "invoice_extraction",
        "schema": {
            "type": "object",
            "properties": {
                "vendor": {"type": ["string", "null"]},
                "date": {"type": ["string", "null"]},
                "total": {"type": ["number", "string", "null"]},
                "line_items": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "description": {"type": ["string", "null"]},
                            "quantity": {"type": ["number", "string", "null"]},
                            "unit_price": {"type": ["number", "string", "null"]},
                            "amount": {"type": ["number", "string", "null"]},
                        },
                        "required": ["description", "quantity", "unit_price", "amount"],
                        "additionalProperties": False,
                    },
                },
            },
            "required": ["vendor", "date", "total", "line_items"],
            "additionalProperties": False,
        },
        "strict": True,
    }

    response = client.responses.create(
        model="gpt-4.1-mini",
        input=[
            {
                "role": "system",
                "content": (
                    "You extract structured data from invoices. "
                    "Return only fields matching the provided JSON schema."
                ),
            },
            {
                "role": "user",
                "content": f"Extract the invoice fields from the following text:\n\n{invoice_text}",
            },
        ],
        response_format={"type": "json_schema", "json_schema": schema},
    )

    content = getattr(response, "output_text", None)
    if not content:
        # Fallback for SDK response shapes that don't expose output_text directly
        try:
            content = response.output[0].content[0].text
        except Exception:
            content = "{}"

    data = json.loads(content)

    def normalize_number(value: Any) -> Any:
        if isinstance(value, (int, float)) or value is None:
            return value
        if isinstance(value, str):
            s = value.strip().replace(",", "")
            try:
                if "." in s:
                    return float(s)
                return int(s)
            except Exception:
                return value
        return value

    normalized_line_items: List[Dict[str, Any]] = []
    for item in data.get("line_items", []) or []:
        normalized_line_items.append(
            {
                "description": item.get("description"),
                "quantity": normalize_number(item.get("quantity")),
                "unit_price": normalize_number(item.get("unit_price")),
                "amount": normalize_number(item.get("amount")),
            }
        )

    return {
        "vendor": data.get("vendor"),
        "date": data.get("date"),
        "total": normalize_number(data.get("total")),
        "line_items": normalized_line_items,
    }
